// ## Concatenates adjacent tokens into a single new token.
// The resulting token sequence is immediately rescanned for further expansion.

#define SUFFIX _Field
#define CREATE_NAME(Prefix) Prefix ## SUFFIX

// Transformation: CREATE_NAME(User) -> User_Field
int CREATE_NAME(User) = 1;


// Example: Concatenation followed by Rescan
#define KEY_1A 42
#define CONCAT_AND_EXPAND(X, Y) X ## Y

// 1. Concatenation: CONCAT_AND_EXPAND(KEY_, 1A) -> KEY_1A
// 2. Rescan: KEY_1A expands to 42
int value = CONCAT_AND_EXPAND(KEY_, 1A);
